const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const target = targets.find(item => item.type === 'page');
  if (!target) throw new Error('Chromium page target unavailable');
  const socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; });
  let nextId = 0;
  const pending = new Map();
  const errors = [];
  socket.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.text);
    if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') errors.push(message.params.entry.text);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      message.error ? reject(new Error(message.error.message)) : resolve(message.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    socket.send(JSON.stringify({ id, method, params }));
  });
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: 'http://127.0.0.1:3002/' });
  await sleep(2200);
  const initial = await send('Runtime.evaluate', { expression: `({title: document.title, ready: document.readyState, decks: document.querySelectorAll('.deck').length, errors: [...document.querySelectorAll('script')].map(x => x.src)})`, returnByValue: true });
  await send('Runtime.evaluate', { expression: `document.querySelector('[data-action="demo"][data-deck="a"]').click(); document.querySelector('[data-action="demo"][data-deck="b"]').click()` });
  await sleep(1000);
  const result = await send('Runtime.evaluate', { expression: `({a: document.querySelector('#track-a').textContent, b: document.querySelector('#track-b').textContent, library: document.querySelector('#library-count').textContent, ready: document.readyState})`, returnByValue: true });
  console.log(JSON.stringify({ page: initial.result.value, demoPlayback: result.result.value, browserErrors: errors }, null, 2));
  socket.close();
  if (errors.length || initial.result.value.ready !== 'complete' || initial.result.value.decks !== 2) process.exitCode = 1;
})().catch(error => { console.error(error); process.exitCode = 1; });
